SELECT id, name, email, country_id
FROM customers;

-- main.customers: SELECT by key
SELECT id, name, email, country_id
FROM customers
WHERE id = :id;

-- main.customers: INSERT
INSERT INTO customers (name, email, country_id)
VALUES (:name, :email, :country_id);

-- main.customers: UPDATE
UPDATE customers
SET
    name = :name,
    email = :email,
    country_id = :country_id
WHERE id = :id;

-- main.customers: DELETE
DELETE FROM customers
WHERE id = :id;

-- main.customers: UPSERT
INSERT INTO customers (name, email, country_id)
VALUES (:name, :email, :country_id)
ON CONFLICT (id) DO UPDATE SET
    name = excluded.name,
    email = excluded.email,
    country_id = excluded.country_id;

